// The comment sort types. See here for descriptions:
// https://join-lemmy.org/docs/en/users/03-votes-and-ranking.html.
// Ref: #/components/schemas/CommentSortType
type CommentSortType string

const (
	CommentSortTypeHot           CommentSortType = "hot"
	CommentSortTypeTop           CommentSortType = "top"
	CommentSortTypeNew           CommentSortType = "new"
	CommentSortTypeOld           CommentSortType = "old"
	CommentSortTypeControversial CommentSortType = "controversial"
)

// AllValues returns all CommentSortType values.
func (CommentSortType) AllValues() []CommentSortType {
	return []CommentSortType{
		CommentSortTypeHot,
		CommentSortTypeTop,
		CommentSortTypeNew,
		CommentSortTypeOld,
		CommentSortTypeControversial,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s CommentSortType) MarshalText() ([]byte, error) {
	switch s {
	case CommentSortTypeHot:
		return []byte(s), nil
	case CommentSortTypeTop:
		return []byte(s), nil
	case CommentSortTypeNew:
		return []byte(s), nil
	case CommentSortTypeOld:
		return []byte(s), nil
	case CommentSortTypeControversial:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *CommentSortType) UnmarshalText(data []byte) error {
	switch CommentSortType(data) {
	case CommentSortTypeHot:
		*s = CommentSortTypeHot
		return nil
	case CommentSortTypeTop:
		*s = CommentSortTypeTop
		return nil
	case CommentSortTypeNew:
		*s = CommentSortTypeNew
		return nil
	case CommentSortTypeOld:
		*s = CommentSortTypeOld
		return nil
	case CommentSortTypeControversial:
		*s = CommentSortTypeControversial
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

