// The federation mode for an item.
// Ref: #/components/schemas/FederationMode
type FederationMode string

const (
	FederationModeAll     FederationMode = "all"
	FederationModeLocal   FederationMode = "local"
	FederationModeDisable FederationMode = "disable"
)

// AllValues returns all FederationMode values.
func (FederationMode) AllValues() []FederationMode {
	return []FederationMode{
		FederationModeAll,
		FederationModeLocal,
		FederationModeDisable,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s FederationMode) MarshalText() ([]byte, error) {
	switch s {
	case FederationModeAll:
		return []byte(s), nil
	case FederationModeLocal:
		return []byte(s), nil
	case FederationModeDisable:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *FederationMode) UnmarshalText(data []byte) error {
	switch FederationMode(data) {
	case FederationModeAll:
		*s = FederationModeAll
		return nil
	case FederationModeLocal:
		*s = FederationModeLocal
		return nil
	case FederationModeDisable:
		*s = FederationModeDisable
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

