const (
	ListingTypeAll           ListingType = "all"
	ListingTypeLocal         ListingType = "local"
	ListingTypeSubscribed    ListingType = "subscribed"
	ListingTypeModeratorView ListingType = "moderator_view"
	ListingTypeSuggested     ListingType = "suggested"
)

// AllValues returns all ListingType values.
func (ListingType) AllValues() []ListingType {
	return []ListingType{
		ListingTypeAll,
		ListingTypeLocal,
		ListingTypeSubscribed,
		ListingTypeModeratorView,
		ListingTypeSuggested,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s ListingType) MarshalText() ([]byte, error) {
	switch s {
	case ListingTypeAll:
		return []byte(s), nil
	case ListingTypeLocal:
		return []byte(s), nil
	case ListingTypeSubscribed:
		return []byte(s), nil
	case ListingTypeModeratorView:
		return []byte(s), nil
	case ListingTypeSuggested:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *ListingType) UnmarshalText(data []byte) error {
	switch ListingType(data) {
	case ListingTypeAll:
		*s = ListingTypeAll
		return nil
	case ListingTypeLocal:
		*s = ListingTypeLocal
		return nil
	case ListingTypeSubscribed:
		*s = ListingTypeSubscribed
		return nil
	case ListingTypeModeratorView:
		*s = ListingTypeModeratorView
		return nil
	case ListingTypeSuggested:
		*s = ListingTypeSuggested
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

