// Ref: #/components/schemas/PostSortType
type PostSortType string

const (
	PostSortTypeActive        PostSortType = "active"
	PostSortTypeHot           PostSortType = "hot"
	PostSortTypeNew           PostSortType = "new"
	PostSortTypeOld           PostSortType = "old"
	PostSortTypeTop           PostSortType = "top"
	PostSortTypeMostComments  PostSortType = "most_comments"
	PostSortTypeNewComments   PostSortType = "new_comments"
	PostSortTypeControversial PostSortType = "controversial"
	PostSortTypeScaled        PostSortType = "scaled"
)

// AllValues returns all PostSortType values.
func (PostSortType) AllValues() []PostSortType {
	return []PostSortType{
		PostSortTypeActive,
		PostSortTypeHot,
		PostSortTypeNew,
		PostSortTypeOld,
		PostSortTypeTop,
		PostSortTypeMostComments,
		PostSortTypeNewComments,
		PostSortTypeControversial,
		PostSortTypeScaled,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s PostSortType) MarshalText() ([]byte, error) {
	switch s {
	case PostSortTypeActive:
		return []byte(s), nil
	case PostSortTypeHot:
		return []byte(s), nil
	case PostSortTypeNew:
		return []byte(s), nil
	case PostSortTypeOld:
		return []byte(s), nil
	case PostSortTypeTop:
		return []byte(s), nil
	case PostSortTypeMostComments:
		return []byte(s), nil
	case PostSortTypeNewComments:
		return []byte(s), nil
	case PostSortTypeControversial:
		return []byte(s), nil
	case PostSortTypeScaled:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *PostSortType) UnmarshalText(data []byte) error {
	switch PostSortType(data) {
	case PostSortTypeActive:
		*s = PostSortTypeActive
		return nil
	case PostSortTypeHot:
		*s = PostSortTypeHot
		return nil
	case PostSortTypeNew:
		*s = PostSortTypeNew
		return nil
	case PostSortTypeOld:
		*s = PostSortTypeOld
		return nil
	case PostSortTypeTop:
		*s = PostSortTypeTop
		return nil
	case PostSortTypeMostComments:
		*s = PostSortTypeMostComments
		return nil
	case PostSortTypeNewComments:
		*s = PostSortTypeNewComments
		return nil
	case PostSortTypeControversial:
		*s = PostSortTypeControversial
		return nil
	case PostSortTypeScaled:
		*s = PostSortTypeScaled
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

